import{_ as o,a as r}from"./chunks/contour-field.B-s0Ko3S.js";import{_ as i,C as n,o as l,c as d,j as a,a as c,E as h,a6 as t}from"./chunks/framework.DIp0zHSV.js";const w=JSON.parse('{"title":"LCARdS 2026.07.01.1","description":"New colour picker, contour field background, lcards.play_sound, connectivity overlay rewrite.","frontmatter":{"version":"2026.07.01.1","date":"2026-07-01T00:00:00.000Z","status":"released","summary":"New colour picker, contour field background, lcards.play_sound, connectivity overlay rewrite.","breaking":true},"headers":[],"relativePath":"releases/2026.07.01.1.md","filePath":"releases/2026.07.01.1.md","lastUpdated":1791928403000}'),u={name:"releases/2026.07.01.1.md"};function p(g,e,m,f,y,b){const s=n("ReleaseMeta");return l(),d("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-07-01-1",tabindex:"-1"},[c("LCARdS 2026.07.01.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-07-01-1","aria-label":'Permalink to "LCARdS 2026.07.01.1"'},"​")],-1)),h(s),e[1]||(e[1]=t('<p>A release focused on bringing some new UX features and a lot of bug fixes. Thank you everyone who report issues you find as you use LCARdS, it&#39;s very much appreciated!</p><p>We have one new (and many fixed) background effects, a significantly improved colour picker, proper state-based colour support for the <code>lcards-slider</code> card, a new HA <code>lcards.play_sound</code> action, and a major overhaul of the connectivity overlay system. Plus a good number of internal fixes throughout.</p><p><em><strong>Breaking changes:</strong></em> if you use MSD there may be some breaking changes that require a one-time update in config coordinates - See MSD section below.</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="colour-picker-overhaul-372" tabindex="-1">Colour Picker Overhaul (<a href="https://github.com/snootched/lcards/issues/372" target="_blank" rel="noreferrer">#372</a>) <a class="header-anchor" href="#colour-picker-overhaul-372" aria-label="Permalink to &quot;Colour Picker Overhaul ([#372](https://github.com/snootched/lcards/issues/372))&quot;">​</a></h3><p>The LCARdS colour picker has been significantly redesigned:</p>',6)),e[2]||(e[2]=a("p",null,[a("video",{class:"release-shot",src:o,title:"The new LCARdS colour picker",autoplay:"",loop:"",muted:"",playsinline:""})],-1)),e[3]||(e[3]=t('<p>Find colours quickly by:</p><ul><li>using group filter chips that show CSS variables from HA-LCARS/LCARdS theme, HA&#39;s full list, or all.</li><li>filtering colours by family/hue (ie. reds, blues, etc.)</li><li>sorting the list by name, or by gradient</li><li>using a new full custom colour input. A hex-alpha colour entry field is provided via <a href="https://github.com/web-padawan/vanilla-colorful" target="_blank" rel="noreferrer">vanilla-colorful</a> You can have precise control over colour selection including transparency.</li><li>selecting from standard CSS colour list</li><li>providing your own custom string (ie. cascading variables)</li></ul><hr><h3 id="contour-field-background-effect" tabindex="-1">Contour Field Background Effect <a class="header-anchor" href="#contour-field-background-effect" aria-label="Permalink to &quot;Contour Field Background Effect&quot;">​</a></h3><p>Inspired by star chart displays in LCARS - a new animated background preset <strong>Contour Field</strong> is available.</p><p>The effect generates a topographic-style layered field using fractional Brownian motion (fBm) noise, rendered as banded colour contours.</p><img class="release-shot" alt="Contour field background effect" src="'+r+`"><p>Control the look with many configuation options:</p><ul><li><strong>Band count and sparsity:</strong> control how many contour layers are rendered and how dense the field appears</li><li><strong>Colour palette:</strong> use the card&#39;s configured colour array, or fall back gracefully to a default palette</li><li><strong>Fill level and fill colour:</strong> optionally render a fill region below a configurable threshold level</li><li><strong>Blend mode:</strong> hard-edge band boundaries or smooth gradient transitions</li></ul><hr><h3 id="play-sounds-from-automations-lcards-play-sound-ha-action-375" tabindex="-1">Play sounds from Automations: <code>lcards.play_sound</code> HA Action (<a href="https://github.com/snootched/lcards/issues/375" target="_blank" rel="noreferrer">#375</a>) <a class="header-anchor" href="#play-sounds-from-automations-lcards-play-sound-ha-action-375" aria-label="Permalink to &quot;Play sounds from Automations: \`lcards.play_sound\` HA Action ([#375](https://github.com/snootched/lcards/issues/375))&quot;">​</a></h3><p>LCARdS now provides a <code>lcards.play_sound</code> action that can be called from <strong>automations, scripts, or any HA action context</strong><br> This is a targetable action - you can specify target devices and users.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lcards.play_sound</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  event_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">system_ready</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # any configured LCARdS event sound</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">or -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  asset_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lcards_default_tap</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # any registered LCARdS sound asset</span></span></code></pre></div><h2 id="enhancements-fixes" tabindex="-1">Enhancements &amp; Fixes <a class="header-anchor" href="#enhancements-fixes" aria-label="Permalink to &quot;Enhancements &amp; Fixes&quot;">​</a></h2><h3 id="slider-card" tabindex="-1">Slider Card <a class="header-anchor" href="#slider-card" aria-label="Permalink to &quot;Slider Card&quot;">​</a></h3><h4 id="state-based-colour-support-380" tabindex="-1">State-Based Colour Support (<a href="https://github.com/snootched/lcards/issues/380" target="_blank" rel="noreferrer">#380</a>) <a class="header-anchor" href="#state-based-colour-support-380" aria-label="Permalink to &quot;State-Based Colour Support ([#380](https://github.com/snootched/lcards/issues/380))&quot;">​</a></h4><p><code>lcards-slider</code> should now have full parity with <code>lcards-button</code> and <code>lcards-elbow</code> for state-based colour configuration.<br> All style targets - now support the same state/range/attribute colour resolution pipeline.<br> The slider&#39;s indicator visible field now also accepts a template string for conditional show/hide logic.</p><h4 id="slider-card-media-player-volume-display-379" tabindex="-1">Slider Card: Media Player Volume Display (<a href="https://github.com/snootched/lcards/issues/379" target="_blank" rel="noreferrer">#379</a>) <a class="header-anchor" href="#slider-card-media-player-volume-display-379" aria-label="Permalink to &quot;Slider Card: Media Player Volume Display ([#379](https://github.com/snootched/lcards/issues/379))&quot;">​</a></h4><p>When a slider is bound to a <code>media_player</code> entity&#39;s <code>volume_level</code> attribute, the value is now correctly displayed as a percentage (0–100%) rather than the raw HA attribute value (0.0–1.0).<br> Read and write scaling are handled automatically - no configuration required.</p><hr><h3 id="connectivity-overlay-381" tabindex="-1">Connectivity Overlay (<a href="https://github.com/snootched/lcards/issues/381" target="_blank" rel="noreferrer">#381</a>) <a class="header-anchor" href="#connectivity-overlay-381" aria-label="Permalink to &quot;Connectivity Overlay ([#381](https://github.com/snootched/lcards/issues/381))&quot;">​</a></h3><p>The connectivity overlay and its settings panel (lcards-connectivity-tab) have been substantially rewritten.</p><p><em>tl;dr: things should be working properly and consistently now</em></p><ul><li><p>Overlay is now <strong>disabled by default</strong> and is exclusively <em>opt-in</em></p></li><li><p><strong>Configurable Threshold tolerance:</strong> allows for a grace period on websocket disconnection before invoking the overlay. This helps prevent spurious activations on transient disconnections (particularly noticible on HA restarts)</p></li><li><p>The overlay was silently missing the first WebSocket disconnect of a browser session. Root cause related to SoundManager&#39;s connection listener was self-removing.</p></li><li><p>*<em>Scoped settings targeting:</em> Settings per-scope are now spread and targeted, not just a complete config object anymore.</p></li><li><p>The write and clear operations in ScopedSettingsService now accept opts for targeting a specific user or device, enabling more granular control over which clients receive configuration changes.</p></li><li><p>Overriden options now display proper chips indicating the scope where the setting is being derived from.</p></li><li><p><strong>Remote broadcast and config change handling:</strong> mechanism to broadcast a reload command to all connected devices and pages simultaneously.</p></li><li><p><strong>Discard Changes</strong> button restores the panel to the last saved state</p></li></ul><hr><h3 id="msd-design-dimensions-attachment-fixes-fix-377" tabindex="-1">MSD: Design Dimensions &amp; Attachment Fixes (fix <a href="https://github.com/snootched/lcards/issues/377" target="_blank" rel="noreferrer">#377</a>) <a class="header-anchor" href="#msd-design-dimensions-attachment-fixes-fix-377" aria-label="Permalink to &quot;MSD: Design Dimensions &amp; Attachment Fixes (fix [#377](https://github.com/snootched/lcards/issues/377))&quot;">​</a></h3><p><em><strong>Possible breaking changes</strong></em></p><p>Troubleshooting issues as reported in (<a href="https://github.com/snootched/lcards/issues/377" target="_blank" rel="noreferrer">#377</a>) identified several other internal issues related to legacy config schema refactoring and other changes.<br> If you used default attachment point references (not explicit), you may notice some misalignment after the update.<br> This is a one time change you may need to make to your MSD config to compensate. The underlying issue is that the default attachement point is <code>center</code> now and not <code>top_left</code></p><p>This helps:</p><ul><li>correct handling of design dimension values in MSD&#39;s AdvancedRenderer code. Dimensions are now resolved correctly in all layout modes</li><li>control overlay configuration and attachment logic refactored in ConfigProcessor; reduced coupling between overlay wiring and renderer internals</li><li>fix scaling of controls when the MSD size changes (ie. when adapting to window size changes, sidebar activation, etc.)</li></ul><h2 id="other-fixes-improvements" tabindex="-1">Other Fixes &amp; Improvements <a class="header-anchor" href="#other-fixes-improvements" aria-label="Permalink to &quot;Other Fixes &amp; Improvements&quot;">​</a></h2><ul><li>Animation recreation in <code>TriggerManager</code>: <code>on_entity_change</code>-driven animations now correctly recreate rather than stack duplicate instances (report from Discord of animations not stopping when expected.)</li><li>Overlay scope cleanup: animation overlay scopes for buttons and sliders are now properly cleaned up when action handlers are torn down, preventing stale overlays after card removal</li><li><code>max_height</code> / <code>max_width</code> resolution: fixed an edge case where size constraints were not applied when the value was provided as a number without units</li><li>Studio dialog button size: corrected a regression where filter and studio dialog buttons used the deprecated size=&quot;small&quot; attribute (updated to size=&quot;s&quot;)</li><li>Canvas Background Color Resolution: Background animation effects that render to a canvas (textures, screen effects, scanlines, contour field) now apply the correct two-step color resolution: CSS variable lookup followed by ColorUtils.resolveCssVariable(). Previously, colors in canvas contexts could render as literal var(--lcars-...) strings rather than resolved colour values. All built-in background presets and the ScreenEffectManager have been updated.</li></ul><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.06.16.1...2026.07.01.1" target="_blank" rel="noreferrer">2026.06.16.1...2026.07.01.1</a></p>`,34))])}const _=i(u,[["render",p]]);export{w as __pageData,_ as default};
